use vstd::prelude::*;
verus! {
    /// Specification for matrix transpose.
    ///
    /// Given a non-empty rectangular matrix `arr` of 8-bit signed integers,
    /// returns its transpose.
    spec fn transpose(arr: Vec<Vec<i8>>) -> Vec<Vec<i8>>
        // Input must have at least one row
        requires arr.len() > 0;
        // All rows of the input must have the same length
        requires forall |i: usize| i < arr.len() ==>
            arr[i].len() == arr[0].len();

        // Output must have as many rows as the input has columns
        ensures result.len() == arr[0].len();
        // Each row of the output must have as many columns as the input has rows
        ensures forall |j: usize| j < result.len() ==>
            result[j].len() == arr.len();

        // The transpose property: for all valid indices (i, j),
        // result[j][i] == arr[i][j]
        ensures forall |i: usize, j: usize|
            i < arr.len() && j < arr[0].len() ==>
                result[j][i] == arr[i][j];

    pub fn transpose(arr: Vec<Vec<i8>>) -> Vec<Vec<i8>> {
        // number of rows and columns in the input
        let nrows = arr.len();
        let ncols = arr[0].len();

        // we'll build the result as a Vec of length ncols
        let mut result: Vec<Vec<i8>> = Vec::with_capacity(ncols);

        let mut j: usize = 0;
        // build each row j of the result
        while j < ncols
            invariant j <= ncols
            invariant result.len() == j
            invariant forall |jj: usize, ii: usize|
                jj < j && ii < nrows ==>
                result[jj][ii] == arr[ii][jj]
        {
            // row j will have length nrows
            let mut row: Vec<i8> = Vec::with_capacity(nrows);

            let mut i: usize = 0;
            // fill in row[j][i] = arr[i][j]
            while i < nrows
                invariant i <= nrows
                invariant row.len() == i
                invariant forall |ii: usize|
                    ii < i ==>
                    row[ii] == arr[ii][j]
            {
                row.push(arr[i][j]);
                i += 1;
            }

            result.push(row);
            j += 1;
        }

        result
    }
}